import json, os, tempfile
from ocean_sonar.product import quality_trend

def dump(r):
    return json.dumps(r, ensure_ascii=False, separators=(",",":"), allow_nan=False).encode()

def report(layers=2,total=4,valid=3,cov=0.75,te=1,unk=0,worst=1,cp="pass",q="fail"):
    return {"layers":layers,"total":total,"valid":valid,"coverage":cov,
            "terrain_exceed":te,"unknown":unk,"worst":worst,"crosspoint":cp,"quality":q}

d = tempfile.mkdtemp()
def w(r, name):
    p=os.path.join(d,name); open(p,"wb").write(dump(r)); return p

for bad in ([], ("x",), "x", 123, None):
    try:
        quality_trend(bad); print("NO ERROR", bad)
    except (TypeError, ValueError) as e:
        print(type(e).__name__, e)

try: quality_trend([1,2])
except TypeError as e: print("item type:", e)
try: quality_trend(["a",""])
except ValueError as e: print("empty:", e)

r0 = report(valid=2,cov=0.5,te=0,unk=0,worst=0,cp="pass",q="pass")
r1 = report(valid=3,cov=0.75,te=0,unk=0,worst=0,cp="pass",q="pass")
r2 = report(valid=4,cov=1.0,te=0,unk=0,worst=0,cp="pass",q="pass")
res = quality_trend([w(r0,"a"),w(r1,"b"),w(r2,"c")])
assert list(res.keys()) == ["changes","worst","quality"]
assert res["quality"] == "pass"
ch = res["changes"]
assert len(ch)==2
for it in ch:
    assert list(it.keys()) == ["index","coverage_delta","terrain_exceed_delta","unknown_delta","quality"]
    assert type(it["index"]) is int and type(it["terrain_exceed_delta"]) is int and type(it["unknown_delta"]) is int
    assert type(it["coverage_delta"]) is float
assert ch[0]["index"]==1 and ch[0]["coverage_delta"]==0.25
assert res["worst"] is ch[0], "worst tie-break on i"

r3 = report(valid=1,cov=0.25,q="fail")
res2 = quality_trend([w(r1,"b"),w(r3,"d")])
assert res2["changes"][0]["quality"]=="fail" and res2["quality"]=="fail"
assert res2["changes"][0]["coverage_delta"]==-0.5

r4 = report(te=2, valid=3, q="fail")
r5 = report(unk=1, valid=3, q="fail")
assert quality_trend([w(r1,"b"),w(r4,"e")])["quality"]=="fail"
assert quality_trend([w(r1,"b"),w(r5,"f")])["quality"]=="fail"

rf0 = report(q="fail", te=1)
rf1 = report(q="pass", cp="pass", te=0, valid=3)
res3 = quality_trend([w(rf0,"g"),w(rf1,"h")])
assert res3["changes"][0]["quality"]=="pass", res3

rm = report(layers=3)
try: quality_trend([w(r0,"a"),w(rm,"i")])
except ValueError as e: print("layers mismatch:", e)
rt = report(total=5, valid=3, cov=0.6)
try: quality_trend([w(r0,"a"),w(rt,"j")])
except ValueError as e: print("total mismatch:", e)

r6 = report(valid=2,cov=0.5,te=0,unk=0,worst=0,cp="pass",q="pass")
res4 = quality_trend([w(r6,"k"),w(r6,"l")])
cd = res4["changes"][0]["coverage_delta"]
assert cd == 0.0 and str(cd)=="0.0", str(cd)

# bool rejection: True isinstance str? no. bool as item -> TypeError
try: quality_trend([True, "x"])
except TypeError as e: print("bool item:", e)

# load called exactly once per path (spy)
import ocean_sonar.product as pm
calls=[]
orig=pm.load_quality_report
def spy(p):
    calls.append(p); return orig(p)
pm.load_quality_report = spy
try:
    quality_trend([w(r6,"k"),w(r6,"l")])
finally:
    pm.load_quality_report = orig
assert len(calls)==2

# exception propagation unchanged
try: quality_trend([w(r0,"a"), os.path.join(d,"missing")])
except FileNotFoundError: print("FileNotFoundError propagated")
print("all ok")
EOF
